'use strict';
const assert = require('node:assert');
const api = require('./solution');
assert.deepStrictEqual(Object.keys(api), ['createRunSheet']);
const { createRunSheet } = api;

const initial = [
  { id: 'intro', minutes: 5, repeats: 2 },
  { id: 'demo', minutes: 10, repeats: 1 }
];
const sheet = createRunSheet(initial);
assert.deepStrictEqual(sheet.list(), initial);
assert.strictEqual(sheet.totalMinutes(), 20);
assert.notStrictEqual(sheet.list(), sheet.list());
assert.notStrictEqual(sheet.list()[0], initial[0]);
initial[0].minutes = 99;
initial.push({ id: 'late', minutes: 1, repeats: 1 });
assert.deepStrictEqual(sheet.list(), [
  { id: 'intro', minutes: 5, repeats: 2 },
  { id: 'demo', minutes: 10, repeats: 1 }
]);

const replacement = { id: 'intro', minutes: 3, repeats: 4 };
sheet.upsert(replacement);
replacement.minutes = 100;
sheet.upsert({ id: 'end', minutes: 2, repeats: 1 });
assert.deepStrictEqual(sheet.list(), [
  { id: 'intro', minutes: 3, repeats: 4 },
  { id: 'demo', minutes: 10, repeats: 1 },
  { id: 'end', minutes: 2, repeats: 1 }
]);
assert.strictEqual(sheet.totalMinutes(), 24);
assert.strictEqual(sheet.remove('demo'), true);
assert.strictEqual(sheet.remove('missing'), false);
assert.deepStrictEqual(sheet.list().map((entry) => entry.id), ['intro', 'end']);
assert.throws(() => sheet.remove(1), TypeError);

const beforeFailedReplace = sheet.list();
assert.throws(() => sheet.replace([
  { id: 'valid', minutes: 1, repeats: 1 },
  { id: 'valid', minutes: 2, repeats: 2 }
]), RangeError);
assert.deepStrictEqual(sheet.list(), beforeFailedReplace);
assert.throws(() => sheet.replace([
  { id: 'valid', minutes: 1, repeats: 1 },
  { id: 'bad', minutes: '2', repeats: 1 }
]), TypeError);
assert.deepStrictEqual(sheet.list(), beforeFailedReplace);

const newEntries = [{ id: 'only', minutes: 7, repeats: 3 }];
sheet.replace(newEntries);
newEntries[0].repeats = 50;
assert.deepStrictEqual(sheet.list(), [{ id: 'only', minutes: 7, repeats: 3 }]);
sheet.clear();
assert.deepStrictEqual(sheet.list(), []);
assert.strictEqual(sheet.totalMinutes(), 0);

const isolated = createRunSheet();
assert.deepStrictEqual(isolated.list(), []);
isolated.upsert({ id: 'x', minutes: 1, repeats: 1 });
assert.deepStrictEqual(sheet.list(), []);

for (const value of [null, {}, 'entries']) assert.throws(() => createRunSheet(value), TypeError);
for (const entry of [
  null,
  { id: '', minutes: 1, repeats: 1 },
  { id: 1, minutes: 1, repeats: 1 },
  { id: 'x', minutes: '1', repeats: 1 }
]) assert.throws(() => createRunSheet([entry]), TypeError);
for (const entry of [
  { id: 'x', minutes: 0, repeats: 1 },
  { id: 'x', minutes: 1.5, repeats: 1 },
  { id: 'x', minutes: 1, repeats: -1 },
  { id: 'x', minutes: 1, repeats: Number.MAX_SAFE_INTEGER + 1 }
]) assert.throws(() => createRunSheet([entry]), RangeError);
assert.throws(() => createRunSheet([
  { id: 'x', minutes: 1, repeats: 1 },
  { id: 'x', minutes: 2, repeats: 1 }
]), RangeError);

assert.throws(() => createRunSheet([
  { id: 'huge', minutes: Number.MAX_SAFE_INTEGER, repeats: 2 }
]).totalMinutes(), RangeError);
assert.throws(() => createRunSheet([
  { id: 'huge', minutes: Number.MAX_SAFE_INTEGER, repeats: 1 },
  { id: 'one', minutes: 1, repeats: 1 }
]).totalMinutes(), RangeError);

